#!/usr/bin/env node
/**
 * Receipt images on the weekly invoice (Personal receipts, v1): the re-encode
 * child (lib/receipt-image-child.js), the service that runs it and caches its
 * output (lib/receipt-images.js) and the pure page layout (lib/invoice-receipts.js).
 * Every image here is generated by the runner; no real receipt is read.
 *
 *   §1 re-encoded, never embedded as uploaded: a 4000x3000 JPEG with an EXIF
 *      block (GPS text, Orientation 6) and a PNG with a tEXt chunk come out as
 *      upright JPEGs with no Exif and no text, long edge <= 1600 px, <= 1.5 MB,
 *      passing checkImage()
 *   §2 missing or unreadable: no file, a path outside the receipts folder, a
 *      truncated JPEG, a WebP, a PNG header of 20000x20000 -> "unavailable"
 *      (the last two never reach a child); a PDF -> "pdf"
 *   §3 the cache: a second prepare reads it (no new child); a changed receipt or
 *      a bumped version misses it; it never sits under an uploads folder
 *   §4 a child that hangs is killed at the deadline, and the image is "unavailable"
 *   §5 one child at a time, a capped queue: past the cap a job is refused ("busy")
 *   §6 a bounded wait: past it the render goes on without the image, and the
 *      image is cached when the child finishes (`ready`)
 *   §7 safeReceiptImage(): only a JPEG data URI within the byte cap reaches a page
 *   §8 the layout: numbering in line order, headers, notes and links; a PDF
 *      receipt and a missing one; the 10-image cap; one page per receipt; share
 *      lines carry no receipt note
 *   §9 the templates and field maps: the note cell and its "#receipt-N" link,
 *      the hidden receipt-page template, the page gate in the field map and at
 *      the renderer's sink; with no receipt data an invoice prints as before
 *
 * Pure apart from child processes and a temp folder; no server, no network.
 * Run: node scripts/test-invoice-receipt-images.js    # exits 1 on failure
 */
"use strict";

const fs = require("fs");
const os = require("os");
const path = require("path");
const ROOT = path.join(__dirname, "..");
let pass = 0;
let fail = 0;
function check(label, actual, expected) {
	const a = JSON.stringify(actual);
	const e = JSON.stringify(expected);
	if (a === e) { pass++; console.log(`  ok    ${label}`); return; }
	fail++;
	console.log(`  FAIL  ${label}\n        expected ${e}\n        actual   ${a}`);
}
const section = (t) => console.log(`\n${t}`);
function finish() {
	console.log(`\n${pass} passed, ${fail} failed`);
	process.exit(fail ? 1 : 0);
}

let ri;
let layoutLib;
try {
	ri = require(path.join(ROOT, "lib", "receipt-images.js"));
	layoutLib = require(path.join(ROOT, "lib", "invoice-receipts.js"));
} catch (e) {
	check(`the receipt modules load (${e.message.split("\n")[0]})`, false, true);
	finish();
}
const { Jimp } = require("jimp");
const imageLimits = require(path.join(ROOT, "lib", "image-size.js"));

const TMP = fs.mkdtempSync(path.join(os.tmpdir(), "receipt-images-"));
const RECEIPTS = path.join(TMP, "uploads", "expense-receipts");
const CACHE = path.join(TMP, "storage", "receipt-images");
fs.mkdirSync(RECEIPTS, { recursive: true });

// An APP1 Exif segment: IFD0 with Orientation and an ASCII tag carrying text.
function exifApp1(orientation, text) {
	const ascii = Buffer.from(`${text}\0`, "binary");
	const ifd = Buffer.alloc(2 + 2 * 12 + 4);
	ifd.writeUInt16BE(2, 0);
	ifd.writeUInt16BE(0x0112, 2); ifd.writeUInt16BE(3, 4); ifd.writeUInt32BE(1, 6); ifd.writeUInt16BE(orientation, 10);
	ifd.writeUInt16BE(0x010e, 14); ifd.writeUInt16BE(2, 16); ifd.writeUInt32BE(ascii.length, 18); ifd.writeUInt32BE(8 + ifd.length, 22);
	const tiff = Buffer.concat([Buffer.from([0x4d, 0x4d, 0x00, 0x2a, 0x00, 0x00, 0x00, 0x08]), ifd, ascii]);
	const body = Buffer.concat([Buffer.from("Exif\0\0", "binary"), tiff]);
	const len = body.length + 2;
	return Buffer.concat([Buffer.from([0xff, 0xe1, (len >> 8) & 0xff, len & 0xff]), body]);
}
// A PNG tEXt chunk (CRC included) spliced in after IHDR.
function crc32(buf) {
	let c = ~0;
	for (const b of buf) { c ^= b; for (let k = 0; k < 8; k++) c = (c >>> 1) ^ (0xedb88320 & -(c & 1)); }
	return ~c >>> 0;
}
function withPngText(png, text) {
	const data = Buffer.from(`Comment\0${text}`, "latin1");
	const type = Buffer.from("tEXt");
	const len = Buffer.alloc(4); len.writeUInt32BE(data.length);
	const crc = Buffer.alloc(4); crc.writeUInt32BE(crc32(Buffer.concat([type, data])));
	const ihdrEnd = 8 + 4 + 4 + 13 + 4;
	return Buffer.concat([png.subarray(0, ihdrEnd), len, type, data, crc, png.subarray(ihdrEnd)]);
}
function pngHeader(width, height) {
	const b = Buffer.alloc(33);
	Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]).copy(b, 0);
	b.writeUInt32BE(13, 8); b.write("IHDR", 12, "ascii"); b.writeUInt32BE(width, 16); b.writeUInt32BE(height, 20);
	b[24] = 8; b[25] = 6;
	return b;
}
const put = (name, buf) => { fs.writeFileSync(path.join(RECEIPTS, name), buf); return `/uploads/expense-receipts/${name}`; };
const noisy = (img) => { for (let i = 0; i < img.bitmap.data.length; i += 4) { img.bitmap.data[i] = (i * 7) & 255; img.bitmap.data[i + 1] = (i * 13) & 255; img.bitmap.data[i + 2] = (i * 3) & 255; img.bitmap.data[i + 3] = 255; } return img; };
const decodeJpeg = (dataUri) => Buffer.from(dataUri.slice("data:image/jpeg;base64,".length), "base64");

function scratchChild(name, source) {
	const p = path.join(TMP, name);
	fs.writeFileSync(p, source);
	return p;
}
const HANG = scratchChild("hang-child.js", "process.once('message', () => {}); setInterval(() => {}, 1000);\n");
const SLOW = scratchChild("slow-child.js", "process.once('message', (job) => setTimeout(() => process.send({ jpeg: job.image }, () => process.exit(0)), 400));\n");

(async () => {
	// A phone-sized photo that compresses like one (a gradient, not noise).
	const big = new Jimp({ width: 4000, height: 3000, color: 0xffffffff });
	big.scan(0, 0, 4000, 3000, (x, y, idx) => { big.bitmap.data[idx] = (x >> 4) & 255; big.bitmap.data[idx + 1] = (y >> 4) & 255; big.bitmap.data[idx + 2] = 128; });
	const plainJpeg = await big.getBuffer("image/jpeg", { quality: 90 });
	const J1 = Buffer.concat([plainJpeg.subarray(0, 2), exifApp1(6, "GPS 29.7604 -95.3698 secret-place"), plainJpeg.subarray(2)]);
	const P1 = withPngText(await noisy(new Jimp({ width: 1200, height: 1800, color: 0xffffffff })).getBuffer("image/png"), "secret-text");
	const small = await new Jimp({ width: 60, height: 40, color: 0x336699ff }).getBuffer("image/jpeg", { quality: 80 });
	const pJ1 = put("1760000000001-aaaaaaaaaaaa.jpg", J1);
	const pP1 = put("1760000000002-bbbbbbbbbbbb.png", P1);
	const pCut = put("1760000000003-cccccccccccc.jpg", small.subarray(0, Math.floor(small.length / 2)));
	const pWebp = put("1760000000004-dddddddddddd.webp", Buffer.concat([Buffer.from("RIFF"), Buffer.alloc(4), Buffer.from("WEBPVP8 "), Buffer.alloc(40)]));
	const pHuge = put("1760000000005-eeeeeeeeeeee.png", pngHeader(20000, 20000));
	const pPdf = put("1760000000006-ffffffffffff.pdf", Buffer.from("%PDF-1.4\n1 0 obj\n<<>>\nendobj\ntrailer\n<<>>\n%%EOF\n"));
	const pSmall = put("1760000000007-abababababab.jpg", small);

	section("§1 re-encoded, never embedded as uploaded");
	{
		const svc = ri.createReceiptImageService({ receiptsDir: RECEIPTS, cacheDir: CACHE });
		const a = await svc.prepare({ expenseId: 1, photoData: pJ1 });
		check("the EXIF JPEG comes back as an image", a.status, "image");
		const out = a.status === "image" ? decodeJpeg(a.dataUri) : Buffer.alloc(0);
		const dims = imageLimits.checkImage(out, { types: [imageLimits.JPEG], maxPixels: 1600 * 1600 });
		check("…a JPEG, upright (3000x4000 scaled to 1200x1600)", [dims.ok, dims.width, dims.height], [true, 1200, 1600]);
		check("…with no Exif segment and none of its text", [out.includes(Buffer.from("Exif\0\0", "binary")), out.includes(Buffer.from("secret-place"))], [false, false]);
		check("…within 1.5 MB", out.length <= 1.5 * 1024 * 1024, true);
		const b = await svc.prepare({ expenseId: 2, photoData: pP1 });
		const outP = b.status === "image" ? decodeJpeg(b.dataUri) : Buffer.alloc(0);
		const dimsP = imageLimits.checkImage(outP, { types: [imageLimits.JPEG], maxPixels: 1600 * 1600 });
		check("the PNG with a text chunk comes back as a JPEG, 1067x1600, no text", [b.status, dimsP.ok, dimsP.width, dimsP.height, outP.includes(Buffer.from("secret-text"))], ["image", true, 1067, 1600, false]);
		const c = await svc.prepare({ expenseId: 7, photoData: pSmall });
		const dimsS = imageLimits.checkImage(decodeJpeg(c.dataUri || "data:image/jpeg;base64,"), { types: [imageLimits.JPEG], maxPixels: 1e6 });
		check("a small image is never scaled up: 60x40 stays 60x40", [c.status, dimsS.width, dimsS.height], ["image", 60, 40]);
		const legacy = await svc.prepare({ expenseId: 8, photoData: `data:image/png;base64,${P1.toString("base64")}` });
		const outL = legacy.status === "image" ? decodeJpeg(legacy.dataUri) : Buffer.alloc(0);
		check("an old row's inline PNG data URI is re-encoded the same way", [legacy.status, outL.includes(Buffer.from("secret-text"))], ["image", false]);
		check("the re-encode ran in a child process", svc.stats().forks >= 3, true);
	}

	section("§2 missing or unreadable");
	{
		const svc = ri.createReceiptImageService({ receiptsDir: RECEIPTS, cacheDir: path.join(TMP, "storage", "c2") });
		const st = async (photoData) => (await svc.prepare({ expenseId: 9, photoData })).status;
		check("no photo, a deleted file, a path outside the receipts folder", [await st(""), await st("/uploads/expense-receipts/1760000009999-000000000000.jpg"), await st("/uploads/other/x.jpg")], ["unavailable", "unavailable", "unavailable"]);
		check("a traversal attempt reads only inside the receipts folder", await st("/uploads/expense-receipts/../../../etc/passwd"), "unavailable");
		const forksBefore = svc.stats().forks;
		check("a WebP and a 20000x20000 PNG header are unavailable", [await st(pWebp), await st(pHuge)], ["unavailable", "unavailable"]);
		check("…without starting a child", svc.stats().forks, forksBefore);
		check("a truncated JPEG is unavailable", await st(pCut), "unavailable");
		check("a PDF receipt is 'pdf' (listed, never rendered)", await st(pPdf), "pdf");
		check("…and an old row's inline PDF too", await st("data:application/pdf;base64,JVBERi0xLjQK"), "pdf");
		check("an inline WebP or SVG data URI is unavailable", [await st("data:image/webp;base64,UklGRg=="), await st("data:image/svg+xml;base64,PHN2Zz4=")], ["unavailable", "unavailable"]);
		const kind = (p) => ri.receiptImageKind(p, RECEIPTS);
		check("receiptImageKind(), for a listing without reading: image, pdf, none",
			[kind(pJ1), kind(pP1), kind(pPdf), kind(pWebp), kind(""), kind("/uploads/expense-receipts/1760000009999-000000000000.jpg"), kind("/uploads/other/x.jpg"), kind("data:application/pdf;base64,JVBE"), kind("data:image/png;base64,iVBO")],
			["image", "image", "pdf", "none", "none", "none", "none", "pdf", "image"]);
	}

	section("§3 the cache");
	{
		const svc = ri.createReceiptImageService({ receiptsDir: RECEIPTS, cacheDir: CACHE });
		const forks = svc.stats().forks;
		const again = await svc.prepare({ expenseId: 1, photoData: pJ1 });
		check("a second prepare reads the cache: no child", [again.status, again.cached, svc.stats().forks], ["image", true, forks]);
		const name = ri.receiptImageCacheName(1, pJ1);
		check("named v1-<expense>-<16 hex of the receipt path's sha256>.jpg", /^v1-1-[0-9a-f]{16}\.jpg$/.test(name), true);
		check("…and the file is there", fs.existsSync(path.join(CACHE, name)), true);
		check("a changed receipt misses the cache", ri.receiptImageCacheName(1, pP1) !== name, true);
		check("a bumped version misses the cache", ri.receiptImageCacheName(1, pJ1, "v2") !== name, true);
		let refused = false;
		try { ri.createReceiptImageService({ receiptsDir: RECEIPTS, cacheDir: path.join(TMP, "uploads", "receipt-cache") }); } catch { refused = true; }
		check("a cache folder under uploads/ is refused (the static mount serves it)", refused, true);
	}

	section("§4 a child that hangs");
	{
		const svc = ri.createReceiptImageService({ receiptsDir: RECEIPTS, cacheDir: path.join(TMP, "storage", "c4"), childPath: HANG, timeoutMs: 300 });
		const t0 = Date.now();
		const r = await svc.prepare({ expenseId: 7, photoData: pSmall });
		check("killed at the deadline: unavailable, timed out", [r.status, /timed out/.test(r.reason || "")], ["unavailable", true]);
		check("…within about the deadline", Date.now() - t0 < 3000, true);
		check("…and no child left running", svc.stats().running, 0);
	}

	section("§5 one child at a time, a capped queue");
	{
		const svc = ri.createReceiptImageService({ receiptsDir: RECEIPTS, cacheDir: path.join(TMP, "storage", "c5"), childPath: SLOW, queueCap: 1 });
		const jobs = [1, 2, 3].map((n) => svc.prepare({ expenseId: 100 + n, photoData: pSmall }));
		const out = await Promise.all(jobs);
		check("one runs, one waits its turn, the one past the cap is refused (busy)", out.map((r) => r.status === "unavailable" ? `unavailable:${r.reason}` : r.status).sort(), ["image", "image", "unavailable:busy"]);
		check("never more than one child at once", svc.stats().maxRunning, 1);
	}

	section("§6 a bounded wait");
	{
		const svc = ri.createReceiptImageService({ receiptsDir: RECEIPTS, cacheDir: path.join(TMP, "storage", "c6"), childPath: SLOW });
		const r = await svc.prepare({ expenseId: 200, photoData: pSmall }, { waitMs: 50 });
		check("past the wait: unavailable (preparing), with a ready promise", [r.status, r.reason, typeof (r.ready && r.ready.then)], ["unavailable", "preparing", "function"]);
		const done = await r.ready;
		check("…which settles with the image", done.status, "image");
		const later = await svc.prepare({ expenseId: 200, photoData: pSmall }, { waitMs: 50 });
		check("…and the next render reads it from the cache", [later.status, later.cached], ["image", true]);
	}

	section("§7 safeReceiptImage()");
	{
		const jpegUri = `data:image/jpeg;base64,${small.toString("base64")}`;
		const safe = layoutLib.safeReceiptImage;
		check("a JPEG data URI passes (one gate, shared by both modules)", [safe(jpegUri), ri.safeReceiptImage === safe], [jpegUri, true]);
		check("a PNG data URI, a URL, an SVG, a JPEG prefix with markup after it, and junk do not",
			[safe(`data:image/png;base64,${small.toString("base64")}`), safe("https://example.test/a.jpg"), safe("data:image/svg+xml;base64,PHN2Zz4="), safe("data:image/jpeg;base64,AAAA\"><script>"), safe({})],
			[null, null, null, null, null]);
		check("over the byte cap does not", safe(`data:image/jpeg;base64,${"A".repeat(layoutLib.RECEIPT_IMAGE_DATA_URI_MAX_LENGTH)}`) === null, true);
	}

	section("§8 the layout");
	{
		const entries = [
			{ rowId: 1, kind: "personal", label: "Personal expense, Pilot #123, Oct 12, 2026", cents: -4500 },
			{ rowId: 2, kind: "share", label: "Fuel share returned, Shell #9, Oct 13, 2026", cents: 2500 },
			{ rowId: 2, kind: "personal", label: "Personal expense, Shell #9, Oct 13, 2026", cents: -10000 },
			{ rowId: 3, kind: "personal", label: "Personal expense, Love's #77, Oct 13, 2026", cents: -4550 },
			{ rowId: 4, kind: "personal_reversed", label: "Personal expense reversed, Diner #2, Oct 14, 2026", cents: 3000 },
		];
		const rows = [{ id: 1, expense_id: 11 }, { id: 2, expense_id: 12 }, { id: 3, expense_id: 13 }, { id: 4, expense_id: 14 }];
		const prepared = new Map([[11, { status: "image", dataUri: "data:image/jpeg;base64,AAAA" }], [12, { status: "pdf" }], [13, { status: "unavailable", reason: "missing" }], [14, { status: "image", dataUri: "data:image/jpeg;base64,BBBB" }]]);
		const out = layoutLib.receiptLayout(entries, rows, prepared);
		check("notes in line order", out.entries.map((e) => e.receiptNote || ""),
			["Receipt 1 of 2, attached after this invoice", "", "PDF receipt on file", "Receipt image not available", "Receipt 2 of 2, attached after this invoice"]);
		check("image lines link to their page", out.entries.map((e) => e.receiptHref || ""), ["#receipt-1", "", "", "", "#receipt-2"]);
		check("one page per image receipt, its header naming the line and the amount",
			out.pages.map((p) => [p.anchor, p.header, p.image]),
			[["receipt-1", "Receipt 1 of 2 - Personal expense, Pilot #123, Oct 12, 2026 - deducted $45.00", "data:image/jpeg;base64,AAAA"],
				["receipt-2", "Receipt 2 of 2 - Personal expense reversed, Diner #2, Oct 14, 2026 - credited $30.00", "data:image/jpeg;base64,BBBB"]]);
		check("a PDF receipt adds no page; the line keeps the expense id for the app's link", out.entries[2].receiptExpenseId, 12);
		const many = Array.from({ length: 12 }, (_, i) => ({ rowId: i + 1, kind: "personal", label: `Personal expense, Store ${i + 1}, Oct 12, 2026`, cents: -100 }));
		const manyRows = many.map((e) => ({ id: e.rowId, expense_id: 500 + e.rowId }));
		const manyPrepared = new Map(manyRows.map((r) => [r.expense_id, { status: "image", dataUri: "data:image/jpeg;base64,CCCC" }]));
		const capped = layoutLib.receiptLayout(many, manyRows, manyPrepared);
		check("at most 10 image pages; the rest say so", [capped.pages.length, capped.entries[10].receiptNote, capped.pages[0].header.startsWith("Receipt 1 of 10 - ")],
			[10, "More receipts on file: open this receipt in the app", true]);
		const twice = layoutLib.receiptLayout(
			[{ rowId: 1, kind: "personal", label: "Personal expense, Pilot #123, Oct 12, 2026", cents: -4500 }, { rowId: 5, kind: "personal_reversed", label: "Personal expense reversed, Pilot #123, Oct 12, 2026", cents: 4500 }],
			[{ id: 1, expense_id: 11 }, { id: 5, expense_id: 11 }], prepared);
		check("one receipt on two lines: one page, both lines point to it", [twice.pages.length, twice.entries.map((e) => e.receiptHref)], [1, ["#receipt-1", "#receipt-1"]]);
		check("no image receipt: no pages", layoutLib.receiptLayout(entries.slice(2, 4), rows, prepared).pages, []);
		const overCap = layoutLib.receiptLayout(entries.slice(0, 1), rows, new Map([[11, { status: "over_cap" }]]));
		check("an image receipt the caller left unprepared past the cap: \"More receipts on file\", no page", [overCap.entries[0].receiptNote, overCap.pages.length],
			["More receipts on file: open this receipt in the app", 0]);
	}

	section("§9 the invoice templates and field maps");
	{
		const maps = require(path.join(ROOT, "lib", "policy-field-maps.js"));
		const { safeReceiptPages } = require(path.join(ROOT, "lib", "policy-renderer.js"));
		const jpegUri = `data:image/jpeg;base64,${small.toString("base64")}`;
		const lines = [
			{ label: "Personal expense, Pilot #123, Oct 12, 2026", amount: "-$45.00", receiptNote: "Receipt 1 of 1, attached after this invoice", receiptHref: "#receipt-1" },
			{ label: "Personal expense, Shell #9, Oct 13, 2026", amount: "-$100.00", receiptNote: "PDF receipt on file", receiptHref: "javascript:alert(1)" },
			{ label: "Personal expense, Love's #77, Oct 13, 2026", amount: "-$45.50", receiptNote: "Receipt image not available", receiptHref: "#receipt-11" },
		];
		const pages = [
			{ anchor: "receipt-1", header: "Receipt 1 of 1 - Personal expense, Pilot #123, Oct 12, 2026 - deducted $45.00", image: jpegUri },
			{ anchor: "receipt-2", header: "a PNG", image: `data:image/png;base64,${small.toString("base64")}` },
			{ anchor: "x\" onerror=\"", header: "a bad anchor", image: jpegUri },
		];
		for (const key of ["service_invoice", "service_invoice_owner_op"]) {
			const f = maps[key]({ personalLines: lines, receiptPages: pages, personalTotal: 190.5 });
			check(`${key}: each line keeps its note; only a "#receipt-N" link survives`, f.personalLines.map((l) => [l.note, l.href]),
				[["Receipt 1 of 1, attached after this invoice", "#receipt-1"], ["PDF receipt on file", ""], ["Receipt image not available", ""]]);
			check(`${key}: only the JPEG page under a receipt-N anchor reaches the renderer`, f.receiptPages.map((p) => p.anchor), ["receipt-1"]);
			const plain = maps[key]({ personalLines: [{ label: "Personal expense, Pilot #123, Oct 12, 2026", amount: "-$45.00" }] });
			check(`${key}: no receipt data, no note and no page (prints as before)`, [plain.personalLines[0].note, plain.personalLines[0].href, plain.receiptPages], ["", "", []]);
		}
		const m = maps.service_invoice_manual({ personalCorrection: true, deductions: [{ date: "Oct 12, 2026", description: "Personal expense, Pilot #123, Oct 12, 2026", amount: 45, receiptNote: "PDF receipt on file" }], lineItems: [], receiptPages: pages });
		check("the correction (manual template): the note follows the description; the same page gate",
			[m.tableRows[1].rows[0][1], m.receiptPages.map((p) => p.anchor)], ["Personal expense, Pilot #123, Oct 12, 2026 (PDF receipt on file)", ["receipt-1"]]);
		check("the renderer's own gate (the sink) drops the same pages and caps at 10",
			[safeReceiptPages(pages).map((p) => p.anchor), safeReceiptPages(Array.from({ length: 12 }, (_, i) => ({ anchor: `receipt-${(i % 10) + 1}`, header: "", image: jpegUri }))).length, safeReceiptPages(undefined)],
			[["receipt-1"], 10, []]);
		for (const file of ["service-invoice.html", "service-invoice-owner-op.html", "service-invoice-manual.html"]) {
			const html = fs.readFileSync(path.join(ROOT, "onboarding-templates", "policy", file), "utf8");
			const section9 = /<section class="document receipt-pages" data-receipt-pages style="display:none">\s*<div class="receipt-page" data-receipt-page-template style="display:none">\s*<h2 data-cell="header"><\/h2>\s*<img data-cell="image" alt="Receipt">\s*<\/div>\s*<\/section>/.test(html);
			check(`${file}: a hidden receipt-page template after the invoice, one sheet per page`, [section9, /\.receipt-page \{ break-before: page; page-break-before: always; \}/.test(html)], [true, true]);
			if (file !== "service-invoice-manual.html") check(`${file}: the Personal row has a note cell`, /data-personal-line-template[\s\S]{0,400}data-cell="note"/.test(html), true);
		}
	}

	fs.rmSync(TMP, { recursive: true, force: true });
	finish();
})().catch((e) => { console.error(e && e.stack || e); try { fs.rmSync(TMP, { recursive: true, force: true }); } catch { /* temp */ } process.exit(1); });
